DATD_HELP = [
    "# datadeep - النماذج والتحقق العميق: مخططات وأنواع وتحقق (pydantic / jsonschema)",
]

_DATD_TOKEN = re.compile(
    r"(?P<dot>\.)?"
    r"(?P<word>(?!\d)[\w\u064B-\u065F\u0670]+)"
    r"(?P<open>\s*\()?"
)

USER_NAMES = set()


def _datadeep_replace(match):
    dot = match.group("dot")
    word = match.group("word")
    open_paren = match.group("open")
    if word in USER_NAMES:
        return match.group(0)
    if dot:
        return match.group(0)
    if word in DATD_CONSTS:
        return DATD_CONSTS[word]
    if word in DATD_FUNCS:
        return DATD_FUNCS[word] + (open_paren or "")
    return match.group(0)


def DATD_SUBSTITUTE(text):
    """يترجم كلمات المكتبة في نص واحد ويُرجع المترجم."""
    if not text:
        return text
    return _DATD_TOKEN.sub(_datadeep_replace, text)
